import java.util.*;

class Solution {
    public boolean traceWord(char[][] board, String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (dfs(board, word, r, c, 0)) return true;
        return false;
    }

    private boolean dfs(char[][] b, String word, int r, int c, int i) {
        if (i == word.length()) return true;             // matched every letter
        if (r < 0 || c < 0 || r >= b.length || c >= b[0].length) return false;
        if (b[r][c] != word.charAt(i)) return false;
        char saved = b[r][c];
        b[r][c] = '#';                                    // mark visited
        boolean found = dfs(b, word, r + 1, c, i + 1) || dfs(b, word, r - 1, c, i + 1)
                     || dfs(b, word, r, c + 1, i + 1) || dfs(b, word, r, c - 1, i + 1);
        b[r][c] = saved;                                  // unmark on the way back
        return found;
    }
}

