function traceWord(board, word) {
  const R = board.length, C = board[0].length, seen = board.map(r => r.map(() => false));
  function dfs(i, j, k) {
    if (board[i][j] !== word[k] || seen[i][j]) return false;
    if (k === word.length - 1) return true;
    seen[i][j] = true;
    for (const [a, b] of [[i + 1, j], [i - 1, j], [i, j + 1], [i, j - 1]])
      if (a >= 0 && a < R && b >= 0 && b < C && dfs(a, b, k + 1)) { seen[i][j] = false; return true; }
    seen[i][j] = false; return false;
  }
  for (let i = 0; i < R; i++) for (let j = 0; j < C; j++) if (dfs(i, j, 0)) return true;
  return false;
}
